@Entity
@Audited                                       // or @Audited on the single property
class Employee { @Id UUID id; String name; Money salary; }

AuditReader reader = AuditReaderFactory.get(entityManager);
Number rev = reader.getRevisionNumberForDate(LocalDateTime.of(2024, 4, 1, 0, 0));
Employee then = reader.find(Employee.class, id, rev);        // as of 2024-04-01
List<?> touched = reader.createQuery()
    .forRevisionsOfEntity(Employee.class, false, true)
    .add(AuditEntity.id().eq(id))
    .add(AuditEntity.property("salary").hasChanged())
    .getResultList();

