final class TemporalCollection<T> {
    private final NavigableMap<LocalDate, T> milestones = new TreeMap<>();
    private final Clock clock;
    TemporalCollection(Clock clock) { this.clock = clock; }

    T get(LocalDate when) {
        Map.Entry<LocalDate, T> e = milestones.floorEntry(when);   // latest start <= when
        if (e == null) throw new NoSuchElementException("not yet effective: " + when);
        return e.getValue();
    }
    T get() { return get(LocalDate.now(clock)); }                  // default: today
    void put(LocalDate from, T value) { milestones.put(from, value); }
}
